static volatile sig_atomic_t hup=0,term=0;
static void sig(int s){if(s==SIGHUP)hup=1;else term=1;}
static string low(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static string trim(string s){size_t a=s.find_first_not_of(" \t"),b=s.find_last_not_of(" \t");return a==string::npos?"":s.substr(a,b-a+1);}
