static bool dir(const string&s){struct stat st;return !s.empty()&&s[0]=='/'&&!stat(s.c_str(),&st)&&S_ISDIR(st.st_mode);}
struct Config{string listen,root,def,host,hostroot,alias,aliasroot,redir,location,index,proxy;vector<string> ups;int port;string ip;long long maxconn,header,htime,idle,wtime,maxreq,depth,utime,body,ttl,cache,rate,burst,drain;};
static bool address(string s,string&ip,int&port){size_t p=s.rfind(':');if(p==string::npos)return false;ip=s.substr(0,p);unsigned long long n;in_addr a;if(inet_pton(AF_INET,ip.c_str(),&a)!=1||!number(s.substr(p+1),n)||n>65535||n==0)return false;port=n;return true;}
static bool load(const string&path,Config&c){ifstream f(path);if(!f)return false;map<string,string> m;string line;while(getline(f,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();line=trim(line);if(line.empty()||line[0]=='#')continue;auto p=line.find('=');if(p==string::npos)return false;string k=trim(line.substr(0,p)),v=trim(line.substr(p+1));if(k.empty()||m.count(k))return false;m[k]=v;}
 vector<string> keys={"listen","root","max_connections","header_bytes","header_timeout_ms","idle_timeout_ms","write_timeout_ms","max_requests","pipeline_depth","default_host","host_root","alias","redirect","index","proxy_prefix","upstreams","upstream_timeout_ms","body_bytes","cache_ttl_ms","cache_bytes","rate_per_second","rate_burst","drain_timeout_ms"};if(m.size()!=keys.size())return false;for(auto&k:keys)if(!m.count(k))return false;
 auto num=[&](string k,long long&x,bool zero=false){unsigned long long n;if(!number(m[k],n)||n>1000000000ULL||(!zero&&!n))return false;x=n;return true;};
 if(!address(m["listen"],c.ip,c.port)||!dir(m["root"])||!num("max_connections",c.maxconn)||!num("header_bytes",c.header)||!num("header_timeout_ms",c.htime)||!num("idle_timeout_ms",c.idle)||!num("write_timeout_ms",c.wtime)||!num("max_requests",c.maxreq)||!num("pipeline_depth",c.depth)||!num("upstream_timeout_ms",c.utime)||!num("body_bytes",c.body)||!num("cache_ttl_ms",c.ttl)||!num("cache_bytes",c.cache)||!num("rate_per_second",c.rate,true)||!num("rate_burst",c.burst)||!num("drain_timeout_ms",c.drain))return false;
 c.listen=m["listen"];c.root=m["root"];c.def=low(m["default_host"]);if(!hostname(c.def))return false;auto pairval=[&](string s,string&a,string&b){size_t p=s.find(':');if(p==string::npos)return false;a=s.substr(0,p);b=s.substr(p+1);return !a.empty()&&!b.empty();};if(!pairval(m["host_root"],c.host,c.hostroot)||!hostname(c.host)||!dir(c.hostroot))return false;c.host=low(c.host);if(!pairval(m["alias"],c.alias,c.aliasroot)||c.alias[0]!='/'||!dir(c.aliasroot))return false;if(!pairval(m["redirect"],c.redir,c.location)||c.redir[0]!='/'||c.location[0]!='/')return false;c.index=m["index"];if(c.index.empty()||c.index=="."||c.index==".."||c.index.find('/')!=string::npos||c.index.find('\\')!=string::npos)return false;c.proxy=m["proxy_prefix"];if(c.proxy.empty()||c.proxy[0]!='/')return false;c.ups=split(m["upstreams"],',');if(c.ups.empty())return false;for(auto&s:c.ups){string ip;int p;if(!address(s,ip,p))return false;}return true;}
