struct Request{string method,target,version,path,query,host,body;vector<Header> h;bool close=false,head=false;};
static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int k;unsigned v;if(c>=0xc2&&c<=0xdf)k=1,v=c&31;else if(c>=0xe0&&c<=0xef)k=2,v=c&15;else if(c>=0xf0&&c<=0xf4)k=3,v=c&7;else return false;if(i+k>s.size())return false;for(int j=0;j<k;j++){unsigned char x=s[i++];if((x&192)!=128)return false;v=(v<<6)|(x&63);}if((k==2&&v<0x800)||(k==3&&v<0x10000)||v>0x10ffff||(v>=0xd800&&v<=0xdfff))return false;}return true;}
static int hex(char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;return -1;}
