static bool parseheaders(const string&s,vector<Header>&h){size_t p=0;while(p<s.size()){size_t e=s.find("\r\n",p);if(e==string::npos)return false;string l=s.substr(p,e-p);p=e+2;if(l.empty())return p==s.size();if(l[0]==' '||l[0]=='\t')return false;size_t q=l.find(':');if(q==string::npos||!token(l.substr(0,q)))return false;string v=l.substr(q+1);for(unsigned char c:v)if(c==0||c==127||(c<32&&c!='\t'))return false;h.push_back({low(l.substr(0,q)),trim(v)});}return false;}
static vector<string> vals(const vector<Header>&h,string n){vector<string> v;for(auto&x:h)if(x.name==n)v.push_back(x.val);return v;}
static set<string> connectionnames(const vector<Header>&h){set<string>s={"connection","keep-alive","proxy-connection","proxy-authenticate","proxy-authorization","transfer-encoding","upgrade","te","trailer"};for(auto &v:vals(h,"connection"))for(auto &t:split(v,','))s.insert(low(trim(t)));return s;}
static bool hastoken(const vector<Header>&h,string n,string t){for(auto&v:vals(h,n))for(auto x:split(v,','))if(low(trim(x))==t)return true;return false;}
