static bool chunkext(const string&s,size_t p){auto ws=[&](){while(p<s.size()&&(s[p]==' '||s[p]=='\t'))p++;};auto tok=[&](){size_t a=p;while(p<s.size()&&token(s.substr(p,1)))p++;return p>a;};while(p<s.size()){ws();if(p==s.size()||s[p++]!=';')return false;ws();if(!tok())return false;ws();if(p<s.size()&&s[p]=='='){p++;ws();if(p<s.size()&&s[p]=='"'){p++;bool done=false;while(p<s.size()){unsigned char c=s[p++];if(c=='"'){done=true;break;}if(c=='\\'){if(p==s.size())return false;c=s[p++];}if(c<32||c==127)return false;}if(!done)return false;}else if(!tok())return false;}}return true;}
static int chunks(const string&s,size_t start,long long limit,string&out,size_t&consumed){size_t p=start;out.clear();for(;;){size_t e=s.find("\r\n",p);if(e==string::npos)return s.size()-p>8192?-1:0;string line=s.substr(p,e-p);size_t end=0;while(end<line.size()&&hex(line[end])>=0)end++;if(end==0||end>16||!chunkext(line,end))return -1;unsigned long long z=0;for(size_t i=0;i<end;i++){int x=hex(line[i]);if(z>(~0ULL-x)/16)return -1;z=z*16+x;}p=e+2;if(z>(unsigned long long)limit-out.size())return -2;if(z==0){size_t t=p;for(;;){e=s.find("\r\n",p);if(e==string::npos)return s.size()-t>8192?-1:0;if(e-p>8192||e-t>8192)return -1;if(e==p){consumed=e+2;return 1;}string h=s.substr(p,e-p);size_t col=h.find(':');if(col==string::npos||!token(h.substr(0,col)))return -1;for(unsigned char c:h.substr(col+1))if(c==0||c==127||(c<32&&c!='\t'))return -1;p=e+2;}}if(z>s.size()-p)return 0;if(s.size()-p-z<2)return 0;out.append(s,p,(size_t)z);p+=z;if(s.compare(p,2,"\r\n"))return -1;p+=2;}}
