static void upfail(Conn&c,bool timeout){closeup(c);if(c.req.method!="POST"&&c.attempt<2){startup(c);return;}error(c,timeout?504:502,false);}
static void startup(Conn&c){c.attempt++;c.upidx=rr++%cfg.ups.size();c.generation=generation;int fd=-1;auto &pool=pools[c.upidx];if(!pool.empty()){fd=pool.back();pool.pop_back();}bool reused=fd>=0;if(fd<0)fd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(fd<0){upfail(c,false);return;}c.up=fd;c.upin.clear();c.upout.clear();c.upsent=0;c.upconnected=reused;c.upstart=nowms();string ip;int port;address(cfg.ups[c.upidx],ip,port);if(!reused){sockaddr_in sa{};sa.sin_family=AF_INET;sa.sin_port=htons(port);inet_pton(AF_INET,ip.c_str(),&sa.sin_addr);int r=connect(fd,(sockaddr*)&sa,sizeof(sa));if(r==0)c.upconnected=true;else if(errno!=EINPROGRESS){upfail(c,false);return;}}
 string path=c.req.path.substr(cfg.proxy.size());string raw=c.req.target.substr(0,c.req.target.find('?'));if(raw.rfind(cfg.proxy,0)==0)path=raw.substr(cfg.proxy.size());if(path.empty()||path[0]!='/')path="/"+path;path+=c.req.query;c.upout=c.req.method+" "+path+" HTTP/1.1\r\nHost: "+cfg.ups[c.upidx]+"\r\n";auto hop=connectionnames(c.req.h);hop.insert("host");hop.insert("content-length");for(auto &h:c.req.h)if(!hop.count(h.name))c.upout+=h.name+": "+h.val+"\r\n";if(c.req.method=="POST"||!c.req.body.empty())c.upout+="Content-Length: "+to_string(c.req.body.size())+"\r\n";c.upout+="Connection: keep-alive\r\n\r\n"+c.req.body;upowner[fd]=c.fd;ctl(fd,EPOLLIN|EPOLLOUT|EPOLLRDHUP,EPOLL_CTL_ADD);interest(c);}
static void upprocess(Conn&c,bool eof){size_t e=c.upin.find("\r\n\r\n");if(e==string::npos){if(c.upin.size()>(size_t)cfg.header||eof)upfail(c,false);return;}if(e+4>(size_t)cfg.header){upfail(c,false);return;}size_t l=c.upin.find("\r\n");if(l==string::npos){upfail(c,false);return;}string statusline=c.upin.substr(0,l);if(statusline.size()<12||statusline.rfind("HTTP/1.",0)!=0||(statusline[7]!='0'&&statusline[7]!='1')||statusline[8]!=' '||!isdigit(statusline[9])||!isdigit(statusline[10])||!isdigit(statusline[11])||(statusline.size()>12&&statusline[12]!=' ')){upfail(c,false);return;}for(unsigned char x:statusline)if(x<32||x==127){upfail(c,false);return;}int status=(statusline[9]-'0')*100+(statusline[10]-'0')*10+statusline[11]-'0';vector<Header> h;if(status<200||status>599||!parseheaders(c.upin.substr(l+2,e+4-(l+2)),h)){upfail(c,false);return;}auto cl=vals(h,"content-length"),te=vals(h,"transfer-encoding");if(cl.size()>1||te.size()>1||(!cl.empty()&&!te.empty())){upfail(c,false);return;}size_t b=e+4,consumed=b;string body;bool no=c.req.head||status==204||status==304;unsigned long long n=0;if(!cl.empty()&&!number(cl[0],n)){upfail(c,false);return;}if(!te.empty()&&low(trim(te[0]))!="chunked"){upfail(c,false);return;}if(no){consumed=b;}else if(!te.empty()){int x=chunks(c.upin,b,cfg.body,body,consumed);if(x<0){upfail(c,false);return;}if(!x){if(eof)upfail(c,false);return;}}else if(!cl.empty()){if(n>(unsigned long long)cfg.body){upfail(c,false);return;}if(c.upin.size()-b<n){if(eof)upfail(c,false);return;}body=c.upin.substr(b,n);consumed=b+n;}else {if(c.upin.size()-b>(size_t)cfg.body){upfail(c,false);return;}if(!eof)return;body=c.upin.substr(b);consumed=c.upin.size();}if(consumed!=c.upin.size()){upfail(c,false);return;}bool reusable=!eof&&!hastoken(h,"connection","close")&&statusline.substr(0,8)=="HTTP/1.1"&&(!cl.empty()||!te.empty()||no);auto hop=connectionnames(h);hop.insert("content-length");vector<Header> end;for(auto &x:h)if(!hop.count(x.name))end.push_back(x);closeup(c,reusable);maybe_cache(c,status,end,body);long long len=no?(c.req.head&&!cl.empty()?n:0):body.size();respond(c,status,end,move(body),len);}
static void upstream_event(Conn&c,uint32_t ev){if(c.up<0)return;if(!c.upconnected){int err=0;socklen_t n=sizeof(err);if(getsockopt(c.up,SOL_SOCKET,SO_ERROR,&err,&n)||err){upfail(c,false);return;}c.upconnected=true;}while(c.upsent<c.upout.size()){ssize_t n=send(c.up,c.upout.data()+c.upsent,c.upout.size()-c.upsent,MSG_NOSIGNAL);if(n>0)c.upsent+=n;else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{upfail(c,false);return;}}if(c.up<0)return;ctl(c.up,EPOLLIN|EPOLLRDHUP|(c.upsent<c.upout.size()?EPOLLOUT:0));char buf[16384];bool eof=false;for(;;){ssize_t n=recv(c.up,buf,sizeof(buf),0);if(n>0){c.upin.append(buf,n);if(c.upin.size()>(size_t)(cfg.body+cfg.header+65536)){upfail(c,false);return;}}else if(n==0){eof=true;break;}else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{upfail(c,false);return;}}upprocess(c,eof);}
static bool rateok(){if(!cfg.rate)return true;long long t=nowms();tokens=min((double)cfg.burst,tokens+(t-tokenat)*cfg.rate/1000.0);tokenat=t;if(tokens>=1){tokens-=1;return true;}return false;}
static void process(Conn&c){if(c.up>=0||!c.out.empty()||c.closing)return;if(!c.reqparsed){size_t e=c.in.find("\r\n\r\n");if(e==string::npos){if(c.in.size()>(size_t)cfg.header){error(c,431);return;}for(size_t i=0;i<c.in.size();i++)if(c.in[i]=='\0'||(c.in[i]=='\n'&&(i==0||c.in[i-1]!='\r'))||(c.in[i]=='\r'&&i+1<c.in.size()&&c.in[i+1]!='\n')){error(c,400);return;}return;}if(e+4>(size_t)cfg.header){error(c,431);return;}c.hend=e+4;c.req=Request{};int st=parse_request(c.in.substr(0,c.hend),c.req,cfg);if(st){error(c,st);return;}c.first=0;c.proxy=c.req.path.rfind(cfg.proxy,0)==0;auto cl=vals(c.req.h,"content-length"),te=vals(c.req.h,"transfer-encoding");if(cl.size()>1||te.size()>1||(!cl.empty()&&!te.empty())){error(c,400);return;}unsigned long long n=0;if(!cl.empty()&&!number(cl[0],n)){error(c,400);return;}if(!c.proxy){if(!te.empty()||n){error(c,400);return;}}else {if(!te.empty()&&low(trim(te[0]))!="chunked"){error(c,400);return;}if(n>(unsigned long long)cfg.body){error(c,413);return;}}c.chunked=!te.empty();c.need=n;c.reqparsed=true;}
 size_t consumed=c.hend;if(c.chunked){int r=chunks(c.in,c.hend,cfg.body,c.req.body,consumed);if(r<0){error(c,r==-2?413:400);return;}if(!r)return;}else{if(c.in.size()-c.hend<c.need)return;c.req.body=c.in.substr(c.hend,c.need);consumed+=c.need;}c.in.erase(0,consumed);c.reqparsed=false;c.first=c.in.empty()?0:nowms();if(!rateok()){error(c,429,false,{{"Retry-After","1"}});return;}if(c.proxy){if(c.req.method!="GET"&&c.req.method!="HEAD"&&c.req.method!="POST"){error(c,405,false);return;}if(cachelookup(c))return;c.attempt=0;startup(c);}else local(c);}
static void client_event(Conn&c,uint32_t ev){if(ev&EPOLLOUT){while(c.sent<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.sent,c.out.size()-c.sent,MSG_NOSIGNAL);if(n>0){c.sent+=n;c.write=nowms();}else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{eraseconn(c.fd);return;}}if(c.sent==c.out.size()&&c.filefd>=0){while(c.fileleft>0){ssize_t n=sendfile(c.fd,c.filefd,&c.fileoff,(size_t)min(c.fileleft,1048576LL));if(n>0){c.fileleft-=n;c.write=nowms();}else if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))break;else{eraseconn(c.fd);return;}}if(!c.fileleft){close(c.filefd);c.filefd=-1;}}if(c.sent==c.out.size()&&c.filefd<0){c.out.clear();c.sent=0;c.last=nowms();if(c.closing){eraseconn(c.fd);return;}process(c);interest(c);}}if((ev&EPOLLIN)&&c.out.empty()&&c.up<0){char buf[16384];for(;;){ssize_t n=recv(c.fd,buf,sizeof(buf),0);if(n>0){if(c.in.empty()&&!c.reqparsed)c.first=nowms();c.last=nowms();c.in.append(buf,n);process(c);if(!c.out.empty()||c.up>=0)break;if(c.in.size()>(size_t)(cfg.header+cfg.body+65536)){error(c,413);break;}}else if(n==0){eraseconn(c.fd);return;}else if(errno==EAGAIN||errno==EWOULDBLOCK)break;else{eraseconn(c.fd);return;}}interest(c);}if(ev&(EPOLLERR|EPOLLHUP)){eraseconn(c.fd);return;}if((ev&EPOLLRDHUP)&&c.out.empty()&&c.up<0){eraseconn(c.fd);return;}}
int main(int argc,char**argv){if(argc!=3||string(argv[1])!="--config")return 1;configpath=argv[2];if(!load(configpath,cfg))return 1;signal(SIGPIPE,SIG_IGN);signal(SIGHUP,sig);signal(SIGTERM,sig);signal(SIGINT,sig);listener=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listener<0)return 1;int one=1;setsockopt(listener,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));sockaddr_in sa{};sa.sin_family=AF_INET;sa.sin_port=htons(cfg.port);inet_pton(AF_INET,cfg.ip.c_str(),&sa.sin_addr);if(bind(listener,(sockaddr*)&sa,sizeof(sa))||listen(listener,8192))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;ctl(listener,EPOLLIN,EPOLL_CTL_ADD);pools.resize(cfg.ups.size());tokens=cfg.burst;tokenat=nowms();epoll_event events[512];while(true){long long t=nowms();if(hup){hup=0;Config n;if(load(configpath,n)&&n.listen==cfg.listen){for(auto &v:pools)for(int fd:v)close(fd);pools.clear();pools.resize(n.ups.size());cfg=move(n);generation++;cache.clear();cacheused=0;tokens=cfg.burst;tokenat=t;}}if(term&&!draining){draining=true;drainend=t+cfg.drain;epoll_ctl(ep,EPOLL_CTL_DEL,listener,nullptr);close(listener);listener=-1;}if(draining&&(cs.empty()||t>=drainend))break;int n=epoll_wait(ep,events,512,50);for(int i=0;i<n;i++){int fd=events[i].data.fd;uint32_t ev=events[i].events;if(fd==listener){for(;;){int s=accept4(listener,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(s<0)break;if((long long)cs.size()>=cfg.maxconn||draining){close(s);continue;}auto c=make_unique<Conn>();c->fd=s;c->last=nowms();cs[s]=move(c);ctl(s,EPOLLIN|EPOLLRDHUP,EPOLL_CTL_ADD);}}else {auto u=upowner.find(fd);if(u!=upowner.end()){auto it=cs.find(u->second);if(it!=cs.end())upstream_event(*it->second,ev);}else {auto it=cs.find(fd);if(it!=cs.end())client_event(*it->second,ev);}}}t=nowms();vector<int> kill;for(auto &p:cs){Conn&c=*p.second;if(c.up>=0){if(t-c.upstart>=cfg.utime)upfail(c,true);}else if(!c.out.empty()){if(t-c.write>=cfg.wtime)kill.push_back(c.fd);}else if(c.first){if(t-c.first>=cfg.htime)kill.push_back(c.fd);}else if(t-c.last>=cfg.idle)kill.push_back(c.fd);}for(int fd:kill)eraseconn(fd);}for(auto&p:cs){if(p.second->up>=0)close(p.second->up);if(p.second->filefd>=0)close(p.second->filefd);close(p.first);}for(auto&v:pools)for(int fd:v)close(fd);return 0;}
